# -*- coding: utf-8 -*-
"""Fourteen multilingual articles: eight restored topics, one replacement, five new."""

def W(title, label=None):
    return {
        "kind": "wiki",
        "title": title,
        "url": "https://en.wikipedia.org/wiki/" + title,
        "label": label or title.replace("_", " "),
    }

def H(url, label):
    return {"kind": "html", "url": url, "label": label}

def A(**kwargs):
    kwargs.setdefault("tag_en", "Search Visibility")
    kwargs.setdefault("tag_zh", "搜索可见度")
    kwargs.setdefault("lane", "i18n")
    return kwargs

